t = int(input())

def gen(num):
	if num == '':
		return 0
	elif num == '1':
		return 1
	elif num == '0':
		return 0
	elif num[0] == '0':
		return gen(num[1:])
	else:
		return int(num[1:], 2) + 1 + gen(num[1:]) + 2 ** (len(num) - 2) * (len(num) - 1)

def func(a, b):
	if a < 0 and b >= 0:
		if a + b + 1 == 0:
			return 32 * (b + 1)
		elif a + b + 1 < 0:
			return 32 * (b + 1) + func(a, -(b + 2))
		else:
			return 32 * -a + func(-a, b)
	elif a < 0 and b < 0:
		return 32 * (b - a + 1) - func(-b - 1, -a - 1)
	else:
		if a == 0:
			return gen(bin(b)[2:])
		return gen(bin(b)[2:]) - gen(bin(a - 1)[2:])
for ts in range(t):
